ee:message.ee:set-payload:
%dw 2.0 output application/json var scoreToCheck = vars.getIdentityResponse.identity[0].'score_movil'.Valor default 0 var rangos = vars.getGeoreferenceResponse.georeference[0].Rangos
var matchedRange = rangos filter (rango) -> do { var parts = rango.Codigo splitBy "_" var low = parts[0] as Number var high = parts[1] as Number --- scoreToCheck >= low and scoreToCheck <= high }
var lteScore = (matchedRange[0].Detalle map ((item, index) -> { "Status Score": item.Nombre, "Valor Maximo": item.Valor as Number, "Oferta": vars.initialPayload.model.technology, "Segmento": vars.initialPayload.model.segment }))[0] --- { code: "200", message: "cliente validado exitosamente", result: lteScore }

%dw 2.0 var numberToCheck = vars.getIdentityResponse.identity[0].'score_fija'.Valor default 0 var estrato = vars.getIdentityResponse.identity[0].'score_fija'.Estrato default 0 var rangos = vars.getGeoreferenceResponse.georeference[0].Rangos
var matchedRange = rangos filter (rango) -> do { var parts = rango.Codigo splitBy "_" var low = parts[0] as Number var high = parts[1] as Number --- numberToCheck >= low and numberToCheck <= high }
var matchedDetalle = (matchedRange[0].Detalle default []) filter (d) -> d.Nombre == ("ESTRATO " ++ (estrato as String))
var fixedScore = (matchedDetalle map ((item, index) -> { "Status Score": item.Nombre, "Valor Maximo": item.Valor as Number, "Oferta": vars.initialPayload.model.technology, "Segmento": vars.initialPayload.model.segment }))[0]
output application/json --- { code: "200", message: "cliente validado exitosamente", result: fixedScore }

%dw 2.0
output application/json
---
{
	"DocumentType": vars.initialPayload.documentType match {
		case "CC"  -> 1
        case "CE" -> 2
        else   -> "Invalid input"
	},
	"DocumentNumber": vars.initialPayload.documentNumber,
	"DateExpedition": (vars.initialPayload.dateExpedition as Date) as String {
		format: "yyyy-MM-dd"
	},
	"Surname": vars.initialPayload.firstLastName,
	"Cellphone": vars.initialPayload.cellphone,
	"Adviser": vars.initialPayload.adviser,
	"Channel": vars.initialPayload.channel,
	"Provider": vars.initialPayload.provider,
	"Portal": vars.initialPayload.portal
}
